sys_ux_client_script.script:
function onCardClicked(evt, {api, dispatch, data}) {
    // Get the card data from the event
    console.log('Card clicked event:', evt);
    console.log('Available data:', data);

    // Get the sys_id from the clicked card
    // We need to access the data correctly based on the event structure
    const clickedItem = evt.detail.item || evt.detail || evt;
    console.log('Clicked item:', clickedItem);

    // Try to extract the sys_id
    let sysId;

    // Check if we have data in the standard format
    if (clickedItem.sys_id) {
        sysId = clickedItem.sys_id;
    } 
    // Check if it's in your specific data structure
    else if (clickedItem.additionalFields && clickedItem.additionalFields[0] && clickedItem.additionalFields[0].sys_id) {
        sysId = clickedItem.additionalFields[0].sys_id;
    }
    // Try to get it from your specific data path
    else if (data && data.getvaluebuildertasks_1 && data.getvaluebuildertasks_1.output) {
        const outputData = data.getvaluebuildertasks_1.output;
        // Find the appropriate item - this might need adjustment based on your data structure
        const firstItem = Array.isArray(outputData) ? outputData[0] : outputData;
        if (firstItem && firstItem.additionalFields && firstItem.additionalFields[0]) {
            sysId = firstItem.additionalFields[0].sys_id;
        }
    }

    console.log('Found sys_id:', sysId);

    // Verify we have a sys_id before proceeding
    if (!sysId) {
        console.error('Could not find sys_id in the clicked item data');
        return;
    }

    const tableName = 'samp_sp_vb_task';

    // Open the record in a modal
    api.updateModalConfig({
        size: 'lg',
        modalOpen: true,
        component: {
            name: 'now-record',
            properties: {
                recordId: sysId,
                table: tableName,
                viewable: true,
                editable: true
            }
        }
    });
}
